SELECT tournament.id FROM public.track_tournament tournament LEFT JOIN public.track_tournament_result existing ON existing.id_tournament=tournament.id AND existing.id_user=$2 WHERE tournament.id_level=$1 AND tournament.finalized_at IS NULL AND tournament.start_at<=$3::timestamptz AND tournament.end_at>$3::timestamptz AND (existing.time IS NULL OR existing.time>$4 OR NOT zc_private.record_is_eligible(existing.id_record)) ORDER BY tournament.id
